class Solution {
public:
    int minimumDeleteSum(const std::string& s1, const std::string& s2) {
        const std::size_t n = s1.size();
        const std::size_t m = s2.size();

        int total = 0;
        for (char c : s1) {
            total += static_cast<int>(c);
        }
        for (char c : s2) {
            total += static_cast<int>(c);
        }

        std::vector<std::vector<int>> f(n + 1, std::vector<int>(m + 1, 0));

        for (std::size_t i = 0; i < n; ++i) {
            for (std::size_t j = 0; j < m; ++j) {
                if (s1[i] == s2[j]) {
                    f[i + 1][j + 1] = f[i][j] + static_cast<int>(s1[i]);
                } else {
                    f[i + 1][j + 1] = std::max(f[i][j + 1], f[i + 1][j]);
                }
            }
        }

        return total - f[n][m] * 2;
    }
};

TEST(Solution, MinimumDeleteSum_ExampleCase) {
    Solution sol;
    std::string s1 = "sea";
    std::string s2 = "eat";
    int expected = 231;  // 627 - 2*198
    EXPECT_EQ(sol.minimumDeleteSum(s1, s2), expected);
}

TEST(Solution, MinimumDeleteSum_BothEmpty) {
    Solution sol;
    EXPECT_EQ(sol.minimumDeleteSum("", ""), 0);
}

TEST(Solution, MinimumDeleteSum_OneEmpty) {
    Solution sol;
    EXPECT_EQ(sol.minimumDeleteSum("a", ""), 97);
    EXPECT_EQ(sol.minimumDeleteSum("", "b"), 98);
}

TEST(Solution, MinimumDeleteSum_IdenticalStrings) {
    Solution sol;
    EXPECT_EQ(sol.minimumDeleteSum("abc", "abc"), 0);
    EXPECT_EQ(sol.minimumDeleteSum("xyz", "xyz"), 0);
}

TEST(Solution, MinimumDeleteSum_NoCommonCharacters) {
    Solution sol;
    std::string s1 = "abc";
    std::string s2 = "def";
    int total = (97 + 98 + 99) + (100 + 101 + 102);  // 294 + 303 = 597
    EXPECT_EQ(sol.minimumDeleteSum(s1, s2), total);
}

TEST(Solution, MinimumDeleteSum_RepeatedCharacters) {
    Solution sol;
    EXPECT_EQ(sol.minimumDeleteSum("bb", "b"), 98);
    EXPECT_EQ(sol.minimumDeleteSum("abcabc", "abc"), 294);
}

TEST(Solution, MinimumDeleteSum_LongStrings) {
    Solution sol;
    std::string s1(1000, 'a');  // 1000 'a's
    std::string s2(500, 'a');   // 500 'a's
    int ascii_a = static_cast<int>('a');  // 97
    int total = (1000 * ascii_a) + (500 * ascii_a);  // 1500 * 97
    int expected = total - 2 * (500 * ascii_a);      // delete 500 'a's from s1
    EXPECT_EQ(sol.minimumDeleteSum(s1, s2), expected);
}
